"""Debug chat: runs turns, prints replies, then the call's variables of interest and events (local helper)."""
import json
import sys
sys.path.insert(0, ".")
import freya  # noqa: E402
from builder.practice import use_system_certificates  # noqa: E402

use_system_certificates()
wid, varsfile, *turns = sys.argv[1:]
variables = json.load(open(varsfile, encoding="utf-8"))
call_id = None
for t in turns:
    body = {"workflowId": wid, "message": t, "customerVariables": variables}
    if call_id:
        body["callId"] = call_id
    try:
        r = freya.api("POST", "/api/v2/chat/message", body)
    except Exception as e:
        print("ERR", str(e)[:200])
        break
    call_id = r.get("callId") or call_id
    print("C:", t, "\nA:", r.get("response", ""), "\n", flush=True)
print("CALL", call_id)
try:
    c = freya.get_call(call_id)
    keys = list(c.keys())
    print("keys", keys)
    for k in ("variables", "callVariables", "state"):
        if k in c:
            v = c[k]
            if isinstance(v, dict):
                for kk in sorted(v):
                    if any(x in kk for x in ("chosen", "cur_week", "ws_", "wc_", "rd_", "of_", "stage", "state", "route", "picked", "sel_", "em_", "email", "oos", "cards_")):
                        print("  ", kk, "=", str(v[kk])[:120])
    msgs = c.get("messages") or []
    for mm in msgs[-40:]:
        s = json.dumps(mm, ensure_ascii=False)
        print("  MSG", s[:300])
except Exception as e:
    print("get_call failed", e)
try:
    freya.api("POST", "/api/v2/chat/end", {"callId": call_id})
except Exception:
    pass

